import * as THREE from 'three';
// Educational motion. All transforms are recomputed from rest; no accumulated drift.
export function organMotionKind(r){const n=r.name.toLowerCase();if(r.layer==='cardiovascular'&&/heart|cardiac atrium|ventricle|atrium|papillary|myocard|interventricular/.test(n)&&!/vein|arter|aort/.test(n))return 'heart';if(r.layer==='visceral'&&(/bronchopulmonary segment/.test(n)||/lung|pulmonary lobe/.test(n)&&!/bronch|hilus|ligament/.test(n)))return 'lung';return null;}
export function motionFactors(kind,t,bpm=72,rpm=14){if(kind==='heart'){const phase=(t*bpm/60)%1,pulse=Math.exp(-Math.pow((phase-.18)/.12,2));return new THREE.Vector3(1-.045*pulse,1-.025*pulse,1-.04*pulse);}const breath=(1-Math.cos(t*rpm/60*Math.PI*2))/2;return new THREE.Vector3(1+.025*breath,1+.018*breath,1+.04*breath);}
export class OrganMotion{
 constructor(){this.groups=[];this.enabled=false;this.bpm=72;this.rpm=14;this.time=0;this.last=null;}
 rebuild(objects,sex){this.restore();const groups=new Map();for(const o of objects.values()){if((o.userData.record.sex||'male')!==sex)continue;const kind=organMotionKind(o.userData.record);if(!kind)continue;const key=kind==='heart'?'heart':'lung'+(o.userData.worldCenter.x>0?'l':'r');if(!groups.has(key))groups.set(key,{kind,items:[],box:new THREE.Box3()});const g=groups.get(key);g.items.push(o);g.box.expandByObject(o);o.userData.restScale??=o.scale.clone();}this.groups=[...groups.values()].map(g=>({...g,center:g.box.getCenter(new THREE.Vector3())}));}
 restore(){if(!this.dirty){this.last=null;return;}this.dirty=false;for(const g of this.groups)for(const o of g.items){o.position.copy(o.userData.basePosition);o.scale.copy(o.userData.restScale);}this.last=null;}
 tick(ms,allowed){if(!this.enabled||!allowed){this.restore();return false;}if(this.last!==null)this.time+=Math.min(.05,(ms-this.last)/1000);this.last=ms;let any=false;for(const g of this.groups){const s=motionFactors(g.kind,this.time,this.bpm,this.rpm);for(const o of g.items){if(!o.visible)continue;any=true;this.dirty=true;const pivot=o.parent.worldToLocal(g.center.clone());o.position.copy(o.userData.basePosition).sub(pivot).multiply(s).add(pivot);o.scale.copy(o.userData.restScale).multiply(s);}}return any;}
}
